import { useEffect, useRef } from 'react';
import {
  useThorVG,
  type Canvas,
  type Picture,
  type Scene,
  type Shape,
  type Text,
} from '@thorvg/react-native-thorvg';
import { loadBytes, loadText } from './assets';

const Example = () => {
  const TVG = useThorVG({ renderer: 'sw' });
  const canvasRef = useRef<Canvas>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!TVG || !canvas) return;
    let active = true;

    // Native example: Duplicate.cpp

    (async () => {
      //Duplicate Shapes
      {
        //Original Shape
        const shape1 = new TVG.Shape();
        shape1.appendRect(7.5, 7.5, 150, 150);
        shape1.appendRect(165, 7.5, 75, 75);

        shape1.stroke({ width: 2.25, color: [0, 255, 0, 255], dash: [3, 3] });
        shape1.fill(255, 0, 0, 255);

        //Duplicate Shape, Switch fill method
        const shape2 = shape1.duplicate<Shape>();
        shape2.translate(0, 165);

        const fill = new TVG.LinearGradient(7.5, 7.5, 330, 150);
        fill.setStops([0, [0, 0, 0, 255]], [1, [255, 255, 255, 255]]);

        shape2.fill(fill);

        //Duplicate Shape 2
        const shape3 = shape2.duplicate<Shape>();
        shape3.translate(0, 330);

        canvas.add(shape1);
        canvas.add(shape2);
        canvas.add(shape3);
      }

      //Duplicate Scene
      {
        //Create a Scene1
        const scene1 = new TVG.Scene();

        const shape1 = new TVG.Shape();
        shape1.appendRect(0, 0, 300, 300, { rx: 37.5, ry: 37.5 });
        shape1.fill(0, 255, 0, 255);
        scene1.add(shape1);

        const shape2 = new TVG.Shape();
        shape2.appendCircle(300, 300, 150, 150);
        shape2.fill(255, 255, 0, 255);
        scene1.add(shape2);

        const shape3 = new TVG.Shape();
