        shape3.fill(0, 255, 255, 255);
        scene1.add(shape3);

        scene1.scale(0.25);
        scene1.translate(300, 0);

        //Duplicate Scene1
        const scene2 = scene1.duplicate<Scene>();
        scene2.translate(450, 0);

        canvas.add(scene1);
        canvas.add(scene2);
      }

      //Duplicate Picture - svg
