        const svgData = await loadText('/assets/svg/2684.svg');
        if (!active) return;

        const picture1 = new TVG.Picture();
        picture1.load(svgData, { type: 'svg' });
        picture1.translate(262.5, 150);
        picture1.scale(3);

        const picture2 = picture1.duplicate<Picture>();
        picture2.translate(412.5, 187.5);

        canvas.add(picture1);
        canvas.add(picture2);
      }

      //Duplicate Picture - raw
