    let active = true;
    let rafId = 0;

    // Native example: EffectDropShadow.cpp

    //background
    const bg = new TVG.Shape();
    bg.appendRect(0, 0, 600, 600);
    bg.fill(255, 255, 255);
    canvas.add(bg);

    let scene1: Scene, scene2: Scene, scene3: Scene;

    (async () => {
      //Prepare a scene for post effects
      {
