        scene3.dropShadow(0, 0, 0, 125, 360 * progress, 15, 0, 100);

        canvas.update();
        canvas.render();
        if (active) rafId = requestAnimationFrame(animate);
      };
      animate();
    })();

    return () => {
      active = false;
      cancelAnimationFrame(rafId);
    };
  }, [TVG]);

  if (!TVG) return null;
  return (
    <TVG.Canvas
      ref={canvasRef}
      width={600}
      height={600}
      style={{ width: '100%', aspectRatio: 1 }}
    />
