import { useEffect, useRef } from 'react';
import { useThorVG, type Canvas } from '@thorvg/react-native-thorvg';

const Example = () => {
  const TVG = useThorVG({ renderer: 'sw' });
  const canvasRef = useRef<Canvas>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!TVG || !canvas) return;

    // Native example: FillSpread.cpp

    //Radial grad
    {
      let x1,
        y1 = 60.0,
        r = 90.0;

      //Pad
      x1 = 30.0;
      const shape1 = new TVG.Shape();
      shape1.appendRect(x1, y1, 2.0 * r, 2.0 * r);

      const fill1 = new TVG.RadialGradient(
        x1 + r,
        y1 + r,
        30.0,
        x1 + r,
        y1 + r,
        0.0
      );
      fill1.setStops(
        [0.0, [127, 39, 255, 255]],
        [0.33, [159, 112, 253, 255]],
        [0.66, [253, 191, 96, 255]],
        [1.0, [255, 137, 17, 255]]
      );
      fill1.spread(TVG.GradientSpread.Pad);
      shape1.fill(fill1);

      canvas.add(shape1);

      //Reflect
      x1 = 215.0;
      const shape2 = new TVG.Shape();
      shape2.appendRect(x1, y1, 2.0 * r, 2.0 * r);

