import { useEffect, useRef } from 'react';
import {
  useThorVG,
  type Canvas,
  type LottieAnimation,
  type Paint,
  type Picture,
} from '@thorvg/react-native-thorvg';
import { loadBytes, loadText } from './assets';

const Example = () => {
  const TVG = useThorVG({ renderer: 'sw' });
  const canvasRef = useRef<Canvas>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!TVG || !canvas) return;
    let active = true;
    let rafId = 0;

    // Native example: LottieSlot.cpp

    const NUM_PER_ROW = 4;
    const NUM_PER_COL = 4;

    const slots: LottieAnimation[] = [];
    const size = 600 / NUM_PER_ROW;

    const sizing = (picture: Picture, counter: number) => {
      picture.origin(0.5, 0.5);

      //image scaling preserving its aspect ratio
      const { width: w, height: h } = picture.size();
      picture.scale(w > h ? size / w : size / h);
      picture.translate(
        (counter % NUM_PER_ROW) * size + size / 2,
        Math.floor(counter / NUM_PER_ROW) * (600 / NUM_PER_COL) + size / 2
      );
    };

    (async () => {
      //The default font for fallback in case
      const fontData = await loadBytes('/fonts/PublicSans-Regular.ttf');
      if (!active) return;
      TVG.Font.load('PublicSans-Regular', fontData, { type: 'ttf' });

      //Background
      const bg = new TVG.Shape();
      bg.appendRect(0, 0, 600, 600);
      bg.fill(75, 75, 75);
      canvas.add(bg);

      const data = await Promise.all(
        [
          'slot0.json',
          'slot1.json',
          'slot2.json',
          'slot3.json',
          'slot4.json',
          'slot5.json',
          'slot6.json',
          'slot7.json',
          'slot8.json',
          'slot9.json',
          'slot10.json',
          'slot11.json',
          'slot12.json',
          'slot13.json',
          'slot14.json',
        ].map((file) => loadText('/assets/lottie/extensions/' + file))
      );

      //The image slot refers to external images, so prefetch them to resolve with.
      const images: Record<string, Uint8Array> = {};
      await Promise.all(
        ['img_0.png', 'logo.png'].map(async (name) => {
          images[name] = await loadBytes(
            '/assets/lottie/extensions/images/' + name
          );
        })
      );

      const resolver = (paint: Paint, src: string) => {
        const image = images[src.split('/').pop() ?? ''];
        if (!image || !(paint instanceof TVG.Picture)) return false;
        paint.load(image, { type: 'png' });
        return true;
      };

      //slot (default)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[0]);

        sizing(picture, 0);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (gradient: color stops, opacity, start, end, height, angle)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[1]);

        const slotJson =
          '{' +
          '"gradient_fill":{"p":{"p":2,"k":{"k":[0,0.1,0.1,0.2,1,1,0.1,0.2,0,0,1,1]}}},' +
          '"gradient_opacity":{"p":{"a":1,"k":[{"i":{"x":[0.833],"y":[0.833]},"o":{"x":[0.167],"y":[0.167]},"s":[100],"t":0},{"i":{"x":[0.833],"y":[0.833]},"o":{"x":[0.167],"y":[0.167]},"s":[30],"t":60},{"s":[100],"t":120}]}},' +
          '"gradient_start":{"p":{"a":1,"k":[{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[-80,-40],"t":0},{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[80,40],"t":60},{"s":[-80,-40],"t":120}]}},' +
          '"gradient_end":{"p":{"a":0,"k":[110,0]}},' +
