          '{"ball_color":{"p":{"a":1,"k":[{"i":{"x":[0.833],"y":[0.833]},"o":{"x":[0.167],"y":[0.167]},"t":7,"s":[0,0.176,0.867]},{"i":{"x":[0.833],"y":[0.833]},"o":{"x":[0.167],"y":[0.167]},"t":22,"s":[0.867,0,0.533]},{"i":{"x":[0.833],"y":[0.833]},"o":{"x":[0.167],"y":[0.167]},"t":37,"s":[0.867,0,0.533]},{"t":51,"s":[0,0.867,0.255]}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 2);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (image)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        picture.resolver(resolver);
        slot.load(data[3]);

        const slotJson =
          '{"path_img":{"p":{"id":"image_0","w":200,"h":300,"u":"images/","p":"logo.png","e":0}}}';
        const slotId = slot.gen(slotJson);
