      }

      //slot (overriden default slot)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[4]);

        const slotJson =
          '{"bg_color":{"p":{"a":0,"k":[1,0.8196,0.2275]}},"check_color":{"p":{"a":0,"k":[0.0078,0.0078,0.0078]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 4);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (duplicate slots with default)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[5]);

        sizing(picture, 5);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (transform: position)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[6]);

        const slotJson =
          '{"position_id":{"p":{"a":1,"k":[{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[100,100],"t":0},{"s":[200,300],"t":100}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 6);
