      }

      //slot (transform: scale)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[7]);

        const slotJson =
          '{"scale_id":{"p":{"a":1,"k":[{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[0,0],"t":0},{"s":[100,100],"t":100}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 7);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (transform: rotation)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[8]);

        const slotJson =
          '{"rotation_id":{"p":{"a":1,"k":[{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[0],"t":0},{"s":[180],"t":100}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 8);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (transform: opacity)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[9]);

        const slotJson =
          '{"opacity_id":{"p":{"a":1,"k":[{"i":{"x":0.833,"y":0.833},"o":{"x":0.167,"y":0.167},"s":[0],"t":0},{"s":[100],"t":100}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 9);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (expression)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[10]);

        const slotJson =
          '{"rect_rotation":{"p":{"x":"var $bm_rt = time * 360;"}},"rect_scale":{"p":{"x":"var $bm_rt = [];$bm_rt[0] = value[0] + Math.cos(2 * Math.PI * time) * 100;$bm_rt[1] = value[1];"}},"rect_position":{"p":{"x":"var $bm_rt = [];$bm_rt[0] = value[0] + Math.cos(2 * Math.PI * time) * 100;$bm_rt[1] = value[1];"}}}';
        const slotId = slot.gen(slotJson);
