      }

      //slot (text)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[11]);

        const slotJson =
          '{"text_doc":{"p":{"k":[{"s":{"f":"Ubuntu Light Italic","t":"ThorVG!","j":0,"s":48,"fc":[1,1,1]},"t":0}]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 11);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (text range)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
        slot.load(data[12]);

        const slotJson = '{"texty":{"p":{"a":0,"k":[1,0.5,0]}}}';
        const slotId = slot.gen(slotJson);
        slot.apply(slotId);

        sizing(picture, 12);
        canvas.add(picture);
        slots.push(slot);
      }

      //slot (bezier path)
      {
        const slot = new TVG.LottieAnimation();
        const picture = slot.picture!;
