    shape3.lineTo(230.25, 273.75);
    shape3.lineTo(149.25, 231.75);
    shape3.lineTo(72.75, 273.75);
    shape3.lineTo(84, 183.75);
    shape3.lineTo(19.5, 120.75);
    shape3.lineTo(109.5, 107.25);
    shape3.close();
    shape3.fill(0, 0, 255, 255);
    shape3.stroke({ width: 7.5, color: [255, 255, 255, 255] });
    shape3.opacity(127);

    scene2.add(shape3);

    //Circle
    const shape4 = new TVG.Shape();

    const cx = 112.5;
    const cy = 112.5;
    const radius = 37.5;
    const halfRadius = radius * 0.552284;

    //Append Paths
    shape4.moveTo(cx, cy - radius);
    shape4.cubicTo(
      cx + halfRadius,
      cy - radius,
      cx + radius,
      cy - halfRadius,
      cx + radius,
      cy
    );
    shape4.cubicTo(
      cx + radius,
      cy + halfRadius,
      cx + halfRadius,
      cy + radius,
      cx,
      cy + radius
    );
    shape4.cubicTo(
      cx - halfRadius,
      cy + radius,
      cx - radius,
      cy + halfRadius,
      cx - radius,
      cy
    );
    shape4.cubicTo(
      cx - radius,
      cy - halfRadius,
      cx - halfRadius,
      cy - radius,
      cx,
      cy - radius
    );
    shape4.close();
    shape4.fill(255, 0, 0, 255);
    shape4.stroke({ width: 7.5, color: [0, 0, 255, 255] });
    shape4.opacity(200);
    shape4.scale(3);
    scene2.add(shape4);

