        .italic()
        .text('Font = "DMSans", Size = 18, Style = Italic')
        .fill(255, 255, 255)
        .translate(0, 88);
      canvas.add(text2);

      const text3 = new TVG.Text();
      text3
        .font('default') //Use any font
        .fontSize(23)
        .text('Kerning Test: VA, AV, TJ, JT')
        .fill(255, 255, 255)
        .translate(0, 132);
      canvas.add(text3);

      const text4 = new TVG.Text();
      text4
        .font('DMSans')
        .fontSize(15)
        .text('Purple Text')
        .fill(255, 0, 255)
        .translate(0, 182);
      canvas.add(text4);

      const text5 = new TVG.Text();
      text5
        .font('DMSans')
        .fontSize(15)
        .text('Gray Text')
        .fill(150, 150, 150)
        .translate(129, 182);
      canvas.add(text5);

      const text6 = new TVG.Text();
      text6
        .font('DMSans')
        .fontSize(15)
        .text('Yellow Text')
        .fill(255, 255, 0)
        .translate(234, 182);
      canvas.add(text6);

      const text7 = new TVG.Text();
      text7
        .font('Pretendard')
        .fontSize(9)
        .text("Transformed Text - 30'")
        .fill(0, 0, 0)
        .translate(352, 234)
